package com.amalaei.engineering;
import java.math.*;
public class CalculatorScenarioTest {
 static void eq(String s,BigDecimal n){if(new BigDecimal(s).compareTo(n)!=0)throw new AssertionError(s+" != "+n);}
 static Calculator buttons(String... keys){Calculator c=new Calculator();for(String key:keys)c.press(key);return c;}
 static void tax(String name,Calculator c,String base,String vat,String total){BigDecimal[] n=Calculator.vat(c.value());eq(base,n[0]);eq(vat,n[1]);eq(total,n[2]);System.out.println(name+": base="+n[0]+", VAT="+n[1]+", total="+n[2]);}
 public static void main(String[] args){tax("One surveying instrument",buttons("1","6","0","8","6",".","9","6","tax"),"16086.96","2413.04","18500.00");Calculator basket=buttons("2","*","1","0","0","0","+","3","*","2","5","0","=","tax");tax("Two devices at 1000 plus three accessories at 250",basket,"2750","412.50","3162.50");Calculator discounted=buttons("3","0","0","0","-","2","5","0","tax");tax("Customer discount before VAT",discounted,"2750","412.50","3162.50");tax("Decimal price three items",buttons("1","9","9",".","9","9","*","3","tax"),"599.97","90.00","689.97");eq("14",buttons("2","+","3","*","4","=").value());eq("10",buttons("2","0","/","4","*","2","=").value());tax("Split 100 over three customers with monetary rounding",buttons("1","0","0","/","3","tax"),"33.33","5.00","38.33");eq("0.3",buttons("0",".","1","+","0",".","2","=").value());eq("-10",buttons("5","*","-","2","=").value());eq("-5",buttons("5","sign").value());eq("12",buttons("1","2","3","back").value());eq("0",buttons("1","C").value());basket.press("9");eq("9",basket.value());Calculator continued=buttons("1","0","+","5","=","*","2","=");eq("30",continued.value());Calculator zero=buttons("8","/","0");try{zero.press("=");throw new AssertionError("Zero division accepted");}catch(IllegalArgumentException ok){System.out.println("Zero division rejected");}zero.press("C");zero.press("2");eq("2",zero.value());Calculator repeat=buttons("1","0","0","tax","tax");tax("Repeated tax does not compound",repeat,"100","15","115");tax("Small monetary rounding",buttons("0",".","1","0","tax"),"0.10","0.02","0.12");eq("1.5",buttons("1",".",".","5").value());eq("16",buttons("8","+","*","2","=").value());eq("3",buttons("9","/","0","back","3","=").value());eq("-5",buttons("5","-","1","0","=").value());Calculator rotated=new Calculator();rotated.restore(repeat.expression(),repeat.finished());rotated.press("4");eq("4",rotated.value());System.out.println("PASS: all user button scenarios on the production calculator engine.");}
}
